function same($a,$b){if($a!==$b)throw new RuntimeException('Expected '.var_export($a,true).' got '.var_export($b,true));}
function check($v){if(!$v)throw new RuntimeException('Assertion failed');}
function raises($class,$run){try{$run();}catch(Throwable $e){if($e instanceof $class)return;throw $e;}throw new RuntimeException('Expected '.$class);}
function test($name,$run){global$passed,$failed;try{$run();$passed++;echo'PASS '.$name.PHP_EOL;}catch(Throwable$e){$failed++;echo'FAIL '.$name.': '.$e->getMessage().PHP_EOL;}}
function child($args){$pipes=[];$p=proc_open(array_merge([PHP_BINARY],$args),[0=>['pipe','r'],1=>['pipe','w'],2=>['pipe','w']],$pipes);if(!is_resource($p))throw new RuntimeException('Cannot start charset child');fclose($pipes[0]);$out=stream_get_contents($pipes[1]);$err=stream_get_contents($pipes[2]);fclose($pipes[1]);fclose($pipes[2]);return[proc_close($p),$out,$err];}
class CharsetTyped {public string $value='';private $private='private';public function privateValue(){return$this->private;}}
class CharsetPayload implements JsonSerializable {private $value;public $calls=0;public function __construct($v){$this->value=$v;}public function jsonSerialize(){++$this->calls;return['value'=>$this->value];}public function value(){return$this->value;}}
class CharsetThrowingPayload implements JsonSerializable {public $error;public function __construct($e){$this->error=$e;}public function jsonSerialize(){throw$this->error;}}
try{
 test('explicit UTF-8 GBK conversion round trips Chinese and normalizes aliases',function(){$gbk=hex2bin('d6d0cec4');same('GBK',myString::normalizeCharset('CP936'));same('UTF-8',myString::normalizeCharset('utf8'));same('中文',myString::convertCharset($gbk,'GBK'));same($gbk,myString::convertCharset('中文','UTF8','CP936'));});
