 test('detection uses explicit candidate order and rejects invalid candidates',function(){same('UTF-8',myString::charset('hello'));same('ISO-8859-1',myString::charset("\xc4\xa2",['latin1','UTF8']));same(false,myString::charset("\x81"));raises(InvalidArgumentException::class,function(){myString::charset('x',[]);});});
 test('UTF-8 UTF-16 and UTF-32 BOMs are recognized before other candidates',function(){foreach(['UTF-8'=>"\xef\xbb\xbf",'UTF-16LE'=>"\xff\xfe",'UTF-16BE'=>"\xfe\xff",'UTF-32LE'=>"\xff\xfe\0\0",'UTF-32BE'=>"\0\0\xfe\xff"]as$encoding=>$bom){$bytes=$bom.mb_convert_encoding('中文',$encoding,'UTF-8');same($encoding,myString::charset($bytes));same('中文',myString::convertCharset($bytes));}same(false,myString::charset("\xff\xfeA\0",['GBK']));});
 test('BOM removal preservation and addition have explicit deterministic behavior',function(){$bom="\xef\xbb\xbf";same('x',myString::convertCharset($bom.'x'));same($bom.'x',myString::convertCharset($bom.'x',null,'UTF8',['bom'=>'preserve']));same($bom.'x',myString::convertCharset('x','UTF8','UTF8',['bom'=>'add']));$be=myString::convertCharset('x','UTF8','UTF16');same("\xfe\xff\0x",$be);raises(InvalidArgumentException::class,function(){myString::convertCharset('x','UTF8','GBK',['bom'=>'add']);});});
 test('explicit BOM conflicts and truncated Unicode are rejected',function(){raises(InvalidArgumentException::class,function(){myString::convertCharset("\xff\xfeA\0",'UTF8');});raises(UnexpectedValueException::class,function(){myString::convertCharset("\xff\xfeA");});});
 test('GB18030 retains supplementary Unicode unlike GBK',function(){$bytes=myString::convertCharset('𠮷😀','UTF8','GB18030');same('𠮷😀',myString::convertCharset($bytes,'GB18030'));same('GB18030',myString::charset($bytes));raises(UnexpectedValueException::class,function(){myString::convertCharset('😀','UTF8','GBK');});});
 test('strict conversion rejects invalid bytes even for identical source and target',function(){raises(UnexpectedValueException::class,function(){myString::convertCharset("\xff",'UTF8','UTF8');});raises(UnexpectedValueException::class,function(){myString::convertCharset("\x81",'GBK','UTF8');});});
 test('replacement and ignore are explicit and restore mbstring global state',function(){$previous=mb_substitute_character();mb_substitute_character('long');try{same('A?B',myString::convertCharset('A😀B','UTF8','GBK',['on_error'=>'replace']));same('AB',myString::convertCharset('A😀B','UTF8','GBK',['on_error'=>'ignore']));same('A�B',myString::convertCharset("A\xffB",'UTF8','UTF8',['on_error'=>'replace']));same('long',mb_substitute_character());raises(UnexpectedValueException::class,function(){myString::convertCharset('😀','UTF8','GBK');});same('long',mb_substitute_character());}finally{mb_substitute_character($previous);}});
 test('invalid names pseudo encodings and unknown options never silently fall back',function(){foreach(['UTF-8//IGNORE','BASE64','HTML-ENTITIES',"UTF8\r\nX",'made-up']as$name)raises(InvalidArgumentException::class,function()use($name){myString::normalizeCharset($name);});raises(InvalidArgumentException::class,function(){myString::convertCharset('x','UTF8','UTF8',['on_error'=>'ignored']);});raises(InvalidArgumentException::class,function(){myString::setCharset('x','UTF8',null,['unknown'=>1]);});});
 test('batch conversion preserves scalar types and does not mutate objects',function(){$gbk=hex2bin('d6d0cec4');$o=(object)['nested'=>(object)['value'=>$gbk],'nil'=>null,'false'=>false,'zero'=>0];$before=serialize($o);$copy=myString::setCharset($o,'UTF8','GBK');same($before,serialize($o));same('中文',$copy->nested->value);same(null,$copy->nil);same(false,$copy->false);same(0,$copy->zero);check($copy!==$o&&$copy->nested!==$o->nested);});
 test('batch conversion retains shared object identity without changing input',function(){$item=(object)['text'=>hex2bin('d6d0cec4')];$copy=myString::setCharset([$item,$item],'UTF8','GBK');check($copy[0]===$copy[1]);same('中文',$copy[0]->text);same(hex2bin('d6d0cec4'),$item->text);});
 test('batch conversion supports public typed data and ArrayObject storage',function(){$o=new CharsetTyped();$o->value=hex2bin('d6d0cec4');$copy=myString::setCharset($o,'UTF8','GBK');same(CharsetTyped::class,get_class($copy));same('中文',$copy->value);same('private',$copy->privateValue());$a=new ArrayObject(['x'=>hex2bin('d6d0cec4')]);$b=myString::setCharset($a,'UTF8','GBK');same('中文',$b['x']);same(hex2bin('d6d0cec4'),$a['x']);});
 test('object cycles array cycles and depth limits terminate with clear errors',function(){$o=new stdClass();$o->self=$o;raises(RuntimeException::class,function()use($o){myString::setCharset($o);});$a=[];$a['self']=&$a;raises(RuntimeException::class,function()use(&$a){myString::setCharset($a);});raises(RuntimeException::class,function(){myString::setCharset(['x'=>['y'=>'z']],'UTF8',null,['max_depth'=>1]);});});
