 test('JSON converts non-UTF8 keys without mutating nested values',function(){$key=hex2bin('d6d0cec4');$data=[$key=>(object)['text'=>$key,'flag'=>false,'number'=>3,'nil'=>null]];$before=serialize($data);$json=myString::toJson($data);same($before,serialize($data));same(['中文'=>['text'=>'中文','flag'=>false,'number'=>3,'nil'=>null]],json_decode($json,true));});
