 test('JSON returns native failures for recursion and resources and keeps business exceptions',function(){$o=new stdClass();$o->self=$o;same(false,myString::toJson($o));same(JSON_ERROR_RECURSION,json_last_error());$r=fopen('php://temp','w+b');try{same(false,myString::toJson($r));same(JSON_ERROR_UNSUPPORTED_TYPE,json_last_error());}finally{fclose($r);}$error=new JsonException('business');try{myString::toJson(new CharsetThrowingPayload($error));}catch(JsonException$e){same($error,$e);return;}throw new RuntimeException('Business exception swallowed');});
